  it('renames and deletes only the selected local session through confirmed actions',async()=>{
    const now=new Date().toISOString();const task={id:'local-session',title:'Synthetic session',phase:'accepted',createdAt:now,updatedAt:now,userRoot:'D:/workspace/demo',agentmemProjectId:'demo-project',correctionCount:0,messages:[{id:'m1',role:'user',text:'sample',createdAt:now}]};let latest:any={...fixture.state,tasks:[task],activeTaskId:task.id};const apiMod=await import('../src/ui/api.js');vi.mocked(apiMod.bootstrap).mockResolvedValue({...fixture,state:latest,csrf:'test'} as any);vi.mocked(apiMod.api).mockImplementation(async(path:string,body:any)=>{if(path==='/api/state')return {state:latest,runtime:fixture.runtime} as any;if(path==='/api/tasks/local-session/rename'){latest={...latest,tasks:[{...task,title:body.title}]};return {} as any;}if(path==='/api/tasks/local-session/delete'){latest={...latest,tasks:[],activeTaskId:null};return {ok:true,id:'local-session'} as any;}return {} as any;});
    const user=userEvent.setup();render(<App/>);await screen.findByRole('button',{name:'Actions for Synthetic session'});fireEvent.click(screen.getByRole('button',{name:'Actions for Synthetic session'}));fireEvent.click(screen.getByRole('menuitem',{name:'Rename'}));const title=await screen.findByRole('textbox',{name:/Session name/});await user.clear(title);await user.type(title,'Renamed local session');expect((title as HTMLInputElement).value).toBe('Renamed local session');fireEvent.click(screen.getByRole('button',{name:'Save name'}));await waitFor(()=>expect(vi.mocked(apiMod.api).mock.calls.some(([url])=>url==='/api/tasks/local-session/rename')).toBe(true));await waitFor(()=>expect(screen.getAllByText('Renamed local session').length).toBeGreaterThan(0));fireEvent.click(screen.getByRole('button',{name:'Actions for Renamed local session'}));fireEvent.click(screen.getByRole('menuitem',{name:'Delete session'}));expect(screen.getByText(/Only Pseudoharness local history is removed/)).toBeTruthy();fireEvent.click(screen.getByRole('button',{name:'Delete local session'}));await screen.findByText('What are we working on?');expect(vi.mocked(apiMod.api).mock.calls.some(([url])=>url==='/api/tasks/local-session/delete')).toBe(true);expect(vi.mocked(apiMod.api).mock.calls.some(([url])=>String(url).includes('agentmem')&&String(url).includes('delete'))).toBe(false);
  });
